import { render, screen, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import ChangelogFilteredList from '@/components/changelog/ChangelogFilteredList';

const replaceMock = jest.fn();
let currentSearch = '';

jest.mock('next/navigation', () => ({
  useSearchParams: () => new URLSearchParams(currentSearch),
  useRouter: () => ({ replace: replaceMock, push: jest.fn() }),
  usePathname: () => '/changelog',
}));

const entries = [
  { slug: '2026-firebase', title: 'Firebase logon shipped', date: '2026-08-01', body: '' },
  { slug: '2026-darkmode', title: 'Dark mode arrives', date: '2026-06-15', body: '' },
  { slug: '2025-launch', title: 'Sandbox launched', date: '2025-11-02', body: '' },
  { slug: '2024-firstpost', title: 'First darkening of docs', date: '2024-03-11', body: '' },
];

beforeEach(() => {
  replaceMock.mockClear();
  currentSearch = '';
});

describe('URL-backed filter state', () => {
  test('AC1: absent params render unfiltered', () => {
    currentSearch = '';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('combobox', { name: /year/i })).toHaveValue('');
    expect(screen.getByRole('searchbox')).toHaveValue('');
    expect(screen.getAllByRole('heading', { level: 3 })).toHaveLength(4);
  });

  test('AC2: ?year=2026 seeds the year filter and filters entries', () => {
    currentSearch = 'year=2026';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('combobox', { name: /year/i })).toHaveValue('2026');
    expect(screen.getByText(/Firebase logon shipped/)).toBeInTheDocument();
    expect(screen.getByText(/Dark mode arrives/)).toBeInTheDocument();
    expect(screen.queryByText(/Sandbox launched/)).not.toBeInTheDocument();
    expect(screen.queryByText(/First darkening of docs/)).not.toBeInTheDocument();
  });

  test('AC3: ?q=dark seeds search and case-insensitively matches title substring', () => {
    currentSearch = 'q=dark';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('searchbox')).toHaveValue('dark');
    expect(screen.getByText(/Dark mode arrives/)).toBeInTheDocument();
    expect(screen.getByText(/First darkening of docs/)).toBeInTheDocument();
    expect(screen.queryByText(/Firebase logon shipped/)).not.toBeInTheDocument();
  });

  test('AC4: year AND q combine', () => {
    currentSearch = 'year=2026&q=dark';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByText(/Dark mode arrives/)).toBeInTheDocument();
    expect(screen.queryByText(/First darkening of docs/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Firebase logon shipped/)).not.toBeInTheDocument();
  });

  test('AC5: unknown year is ignored, not empty', () => {
    currentSearch = 'year=9999';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('combobox', { name: /year/i })).toHaveValue('');
    expect(screen.getAllByRole('heading', { level: 3 })).toHaveLength(4);
  });

  test('AC6: empty ?q= means no filter', () => {
    currentSearch = 'q=';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('searchbox')).toHaveValue('');
    expect(screen.getAllByRole('heading', { level: 3 })).toHaveLength(4);
  });

  test('AC7: whitespace-only ?q= produces no filter', () => {
    currentSearch = 'q=%20%20';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getAllByRole('heading', { level: 3 })).toHaveLength(4);
  });

  test('AC8: non-numeric ?year= is ignored', () => {
    currentSearch = 'year=abc';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('combobox', { name: /year/i })).toHaveValue('');
    expect(screen.getAllByRole('heading', { level: 3 })).toHaveLength(4);
  });

  test('AC9: year change calls router.replace, not push', () => {
    currentSearch = '';
    render(<ChangelogFilteredList entries={entries} />);
    fireEvent.change(screen.getByRole('combobox', { name: /year/i }), { target: { value: '2026' } });
    expect(replaceMock).toHaveBeenCalled();
    const arg = replaceMock.mock.calls[0][0] as string;
    expect(arg).toContain('year=2026');
  });

  test('AC10: every keystroke in search calls router.replace', () => {
    currentSearch = '';
    render(<ChangelogFilteredList entries={entries} />);
    const input = screen.getByRole('searchbox');
    fireEvent.change(input, { target: { value: 'f' } });
    fireEvent.change(input, { target: { value: 'fi' } });
    fireEvent.change(input, { target: { value: 'fir' } });
    expect(replaceMock).toHaveBeenCalledTimes(3);
    const lastArg = replaceMock.mock.calls[2][0] as string;
    expect(lastArg).toContain('q=fir');
  });

  test('AC12: reload with both filters set restores the filtered view', () => {
    currentSearch = 'year=2026&q=firebase';
    render(<ChangelogFilteredList entries={entries} />);
    expect(screen.getByRole('combobox', { name: /year/i })).toHaveValue('2026');
    expect(screen.getByRole('searchbox')).toHaveValue('firebase');
    expect(screen.getByText(/Firebase logon shipped/)).toBeInTheDocument();
    expect(screen.queryByText(/Dark mode arrives/)).not.toBeInTheDocument();
  });

  test('AC13: seeded ?q= does not steal focus on mount', () => {
    currentSearch = 'q=dark';
    render(<ChangelogFilteredList entries={entries} />);
    expect(document.activeElement).not.toBe(screen.getByRole('searchbox'));
    expect(document.activeElement).not.toBe(screen.getByRole('combobox', { name: /year/i }));
  });

  test('AC14: q longer than 200 characters is truncated to 200 and filtered on the prefix', () => {
    const prefix = 'firebase'.padEnd(200, 'x');
    const tail = 'z'.repeat(300);
    currentSearch = 'q=' + encodeURIComponent(prefix + tail);
    render(<ChangelogFilteredList entries={entries} />);
    const input = screen.getByRole('searchbox') as HTMLInputElement;
    expect(input.value).toHaveLength(200);
    expect(input.value).toBe(prefix);
    expect(input.value).not.toContain('z');
  });
});
